#include "device_model.h"
#include "crypto_util.h"
#include "usb_update_model.h"
#include <cJSON.h>
#include <iostream>
#include <fstream>
#include <functional>
#include <stdexcept>
#include <cmath>
using namespace casa;
#define CHECK(x) do{if(!(x))throw std::runtime_error("Device test line "+std::to_string(__LINE__)+": " #x);}while(0)
static std::string read(const std::string &path){std::ifstream f(path);return std::string(std::istreambuf_iterator<char>(f),{});}
int main(int argc,char **argv){CHECK(argc==2);std::string dir=argv[1];
    std::vector<std::pair<const char *,std::function<void()>>> cases={
        {"USB update URL requires explicit configuration command and HTTPS",[]{auto *r=cJSON_Parse(R"({"casa_updates_configure":1,"manifest_url":"https://github.com/carlomicheluzzi/casa-monitor/releases/latest/download/manifest.json"})");auto command=parseUpdateUsb(r);cJSON_Delete(r);CHECK(command.action==UpdateUsbAction::Configure);CHECK(command.manifestUrl.find("github.com")!=std::string::npos);for(auto value:{R"({"casa_updates_configure":1,"manifest_url":"http://example.org/x"})",R"({"casa_updates_configure":true,"manifest_url":"https://example.org/x"})",R"({"casa_updates_configure":1})",R"({"casa_updates_configure":1,"manifest_url":"https://secret@example.org/x"})"}){r=cJSON_Parse(value);CHECK(parseUpdateUsb(r).action==UpdateUsbAction::Invalid);cJSON_Delete(r);}}},
        {"USB check does not configure credentials and ambiguous commands fail",[]{auto *r=cJSON_Parse(R"({"casa_updates_check":1})");CHECK(parseUpdateUsb(r).action==UpdateUsbAction::Check);cJSON_Delete(r);r=cJSON_Parse(R"({"casa_updates_configure":1,"casa_updates_check":1,"manifest_url":"https://example.org/x"})");CHECK(parseUpdateUsb(r).action==UpdateUsbAction::Invalid);cJSON_Delete(r);r=cJSON_Parse(R"({"casa_status":1})");CHECK(parseUpdateUsb(r).action==UpdateUsbAction::None);cJSON_Delete(r);}},
        {"options round trip retains secrets privately",[]{DeviceOptions a,b;a.devices.push_back({"aabbccddeeff","192.168.1.80","admin","secret",4});CHECK(parseOptions(encodeOptions(a).c_str(),b));CHECK(b.devices[0].password=="secret");CHECK(b.screenTimeout==120);CHECK(!b.autoInstall);}},
        {"malformed options rejected",[]{DeviceOptions c;CHECK(!parseOptions("{}",c));CHECK(!parseOptions("{",c));c.screenTimeout=1;CHECK(!validateOptions(c).empty());c={};c.devices.push_back({"aabbccddeeff","8.8.8.8","admin","",4});CHECK(!validateOptions(c).empty());}},
        {"local hosts restrict credentials to intranet",[]{CHECK(localHostAllowed(""));CHECK(localHostAllowed("192.168.1.2"));CHECK(localHostAllowed("shellyem-123456.local"));CHECK(localHostAllowed("10.0.0.1"));CHECK(!localHostAllowed("172.32.1.2"));CHECK(!localHostAllowed("http://192.168.1.2"));CHECK(!localHostAllowed("user@192.168.1.2"));CHECK(!localHostAllowed("127.0.0.1"));}},
        {"HTTPS manifest URL rejects downgrade and credentials",[]{CHECK(httpsUrlAllowed("https://github.com/a/b/releases/download/v1/manifest.json"));CHECK(!httpsUrlAllowed("http://github.com/a"));CHECK(!httpsUrlAllowed("https://a@github.com/x"));CHECK(!httpsUrlAllowed("https://github.com/x\r\nInjected: yes"));}},
        {"identity verifies expected MAC before auth",[]{int gen=0;std::string model;CHECK(parseLocalIdentity(R"({"type":"SHEM","mac":"485519D9CF2F"})","485519d9cf2f",gen,model));CHECK(gen==1);CHECK(model=="SHEM");CHECK(!parseLocalIdentity(R"({"mac":"FFFFFFFFFFFF"})","485519d9cf2f",gen,model));CHECK(parseLocalIdentity(R"({"id":"shelly1pmg4-aabbccddeeff","gen":4,"model":"S4SW-001P16EU"})","aabbccddeeff",gen,model));CHECK(gen==4);}},
        {"Gen1 local EM uses Wh and maps distinct channels",[]{EnergyConfig c;RawReadings r;CHECK(parseLocalStatus(R"({"emeters":[{"power":12,"total":1000,"voltage":230,"is_valid":true},{"power":34,"total":2000,"is_valid":true}]})","485519d9cf2f",1,c,100,5000,r));CHECK(r[0].power==34);CHECK(r[2].power==12);CHECK(r[0].energyWh==2000);CHECK(r[0].local);CHECK(r[0].receivedAt==100);}},
        {"Gen4 local submeter never doubles total",[]{EnergyConfig c;c.sources[4]={"Boiler","aabbccddeeff","switch:0",0};RawReadings r;CHECK(parseLocalStatus(R"({"switch:0":{"apower":1200,"voltage":230,"aenergy":{"total":65}}})","aabbccddeeff",4,c,100,5000,r));CHECK(r[4].power==1200);CHECK(r[4].energyWh==65);CHECK(!r[0].valid);CHECK(!parseLocalStatus(R"({"switch:0":{"apower":true}})","aabbccddeeff",4,c,200,5000,r));CHECK(!r[4].valid);}},
        {"constant local watts remain fresh only on real responses",[]{EnergyModel m;RawReadings r;for(auto &v:r){v={true,true,100,230,10,""};v.local=true;v.receivedAt=100;v.maxAgeMs=5000;}m.ingest(r,100);CHECK(m.complete);m.ingest(r,5100);CHECK(m.complete);m.ingest(r,5101);CHECK(!m.complete);CHECK(std::isnan(m.total));for(auto &v:r)v.receivedAt=5200;m.ingest(r,5200);CHECK(m.complete);}},
        {"local to cloud requires advancing cloud timestamp again",[]{EnergyModel m;RawReadings r;for(auto &v:r){v={true,true,100,230,10,""};v.local=true;v.receivedAt=100;v.maxAgeMs=5000;}m.ingest(r,100);CHECK(m.complete);for(auto &v:r){v.local=false;v.marker="a";}m.ingest(r,200);CHECK(!m.complete);for(auto &v:r)v.marker="b";m.ingest(r,300);CHECK(m.complete);}},
        {"local freshness survives millis wrap",[]{EnergyModel m;RawReadings r;for(auto &v:r){v={true,true,100,230,10,""};v.local=true;v.receivedAt=0xfffffff0u;v.maxAgeMs=5000;}m.ingest(r,0xfffffff0u);m.ingest(r,100);CHECK(m.complete);m.ingest(r,6000);CHECK(!m.complete);}},
        {"local priority stops cloud requests and fallback is per channel",[]{RawReadings local,cloud;for(auto &r:local){r={true,true,100,230,10,""};r.local=true;r.receivedAt=100;r.maxAgeMs=5000;}for(auto &r:cloud)r={true,true,200,230,10,"timestamp"};DeviceOptions o;EnergyConfig c;auto v=combineReadings(local,cloud,c,o,true,100);CHECK(!v.needCloud);CHECK(v.localCount==4);CHECK(v.cloudCount==0);local[0].receivedAt=0;v=combineReadings(local,cloud,c,o,true,5050);CHECK(v.needCloud);CHECK(v.localCount==3);CHECK(v.cloudCount==1);CHECK(v.values[0].power==200);CHECK(v.values[1].power==100);o.cloudFallback=false;v=combineReadings(local,cloud,c,o,true,5050);CHECK(!v.needCloud);CHECK(!v.values[0].valid);o.cloudFallback=true;o.localEnabled=false;v=combineReadings(local,cloud,c,o,true,5050);CHECK(v.needCloud);CHECK(v.cloudCount==4);CHECK(v.localCount==0);}},
        {"no response cannot create a zero house total",[]{RawReadings local,cloud;auto v=combineReadings(local,cloud,EnergyConfig{},DeviceOptions{},false,100);CHECK(v.needCloud);EnergyModel m;m.ingest(v.values,100);CHECK(!m.complete);CHECK(std::isnan(m.total));}},
        {"standby disables only idle display and consumes wake tap",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=30;p.configure(c,0);p.tick(29999,false,false);CHECK(!p.asleep);p.tick(30000,false,false);CHECK(p.asleep);CHECK(!p.touch(true,30001));CHECK(!p.asleep);CHECK(!p.touch(true,30002));CHECK(!p.touch(false,30003));CHECK(p.touch(true,30004));CHECK(p.touch(false,30005));}},
        {"alarm always wakes irrespective of missing-data option",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=15;c.wakeMissing=false;p.configure(c,0);p.tick(15000,false,false);CHECK(p.asleep);p.tick(15001,true,false);CHECK(!p.asleep);p.tick(90000,true,false);CHECK(!p.asleep);}},
        {"missing data wakes after delay and settings inhibit sleep",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=15;p.configure(c,0);p.tick(15000,false,false);CHECK(p.asleep);p.tick(15001,false,true);CHECK(p.asleep);p.tick(25001,false,true);CHECK(!p.asleep);p.tick(50000,false,false,true);CHECK(!p.asleep);}},
        {"persistent missing data wakes once and then permits standby",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=15;p.configure(c,0);p.tick(15000,false,false);CHECK(p.asleep);p.tick(16000,false,true);p.tick(26000,false,true);CHECK(!p.asleep);p.tick(40000,false,true);CHECK(!p.asleep);p.tick(41000,false,true);CHECK(p.asleep);p.tick(120000,false,true);CHECK(p.asleep);}},
        {"recovery rearms the next missing-data notification",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=15;p.configure(c,0);p.tick(1000,false,true);p.tick(11000,false,true);p.tick(26000,false,true);CHECK(p.asleep);p.tick(27000,false,false);p.tick(28000,false,true);p.tick(37999,false,true);CHECK(p.asleep);p.tick(38000,false,true);CHECK(!p.asleep);}},
        {"disabled missing-data wake never restarts the timer",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=15;c.wakeMissing=false;p.configure(c,0);p.tick(1000,false,true);p.tick(15000,false,true);CHECK(p.asleep);p.tick(100000,false,true);CHECK(p.asleep);}},
        {"temporary timeout can be restored independently of settings",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=120;p.configure(c,0);p.setTimeout(15,1000);CHECK(p.timeout()==15);p.tick(16000,false,false);CHECK(p.asleep);p.setTimeout(c.screenTimeout,17000);CHECK(p.timeout()==120);CHECK(!p.asleep);p.tick(136999,false,false);CHECK(!p.asleep);p.tick(137000,false,false);CHECK(p.asleep);}},
        {"never standby and rollover",[]{ScreenPolicy p;DeviceOptions c;c.screenTimeout=0;p.configure(c,0);p.tick(4000000,false,false);CHECK(!p.asleep);c.screenTimeout=15;p.configure(c,0xfffffff0u);p.tick(14990,false,false);CHECK(p.asleep);}},
        {"Digest MD5 known RFC vector",[]{auto h=digestAuthorization("Digest realm=\"testrealm@host.com\", nonce=\"dcd98b7102dd2f0e8b11d0f600bfb0c093\", qop=\"auth\", algorithm=MD5, opaque=\"5ccc069c403ebaf9f0171e9517f40e41\"","GET","/dir/index.html","Mufasa","Circle Of Life","0a4f113b",1);CHECK(h.find("6629fae49393a05397450978507c4ef1")!=std::string::npos);CHECK(h.find("nc=00000001")!=std::string::npos);}},
        {"Digest SHA256 and injection rejection",[]{auto h=digestAuthorization("Digest realm=\"shelly\", nonce=\"abc\", qop=\"auth\", algorithm=SHA-256","GET","/rpc/Shelly.GetStatus","admin","secret","random",2);auto ha1=hashHex("admin:shelly:secret"),ha2=hashHex("GET:/rpc/Shelly.GetStatus");CHECK(h.find(hashHex(ha1+":abc:00000002:random:auth:"+ha2))!=std::string::npos);CHECK(digestAuthorization("Digest realm=\"shelly\", nonce=\"abc\r\n\", qop=\"auth\", algorithm=SHA-256","GET","/","admin","secret","x",1).empty());}},
        {"signed manifest accepts authentic and rejects tamper",[&]{std::string payload;auto envelope=read(dir+"/signed.json"),key=read(dir+"/test-public.pem");CHECK(verifySignedPayload(envelope,key,payload));CHECK(payload==read(dir+"/payload.json"));auto at=envelope.find("payload\":\"");CHECK(at!=std::string::npos);envelope[at+10]=envelope[at+10]=='A'?'B':'A';CHECK(!verifySignedPayload(envelope,key,payload));CHECK(!verifySignedPayload(read(dir+"/signed.json"),read(dir+"/other-public.pem"),payload));CHECK(!verifySignedPayload("{}",key,payload));}},
        {"release compatibility, size and downgrade checks",[&]{ReleaseInfo r;std::string err;auto payload=read(dir+"/payload.json");CHECK(parseRelease(payload.c_str(),10100,0x300000,r,err));CHECK(r.code==10200);CHECK(!parseRelease(payload.c_str(),10200,0x300000,r,err));CHECK(!parseRelease(payload.c_str(),10100,1024,r,err));auto at=payload.find("waveshare");payload[at]='X';CHECK(!parseRelease(payload.c_str(),10100,0x300000,r,err));}}
    };
    for(auto &c:cases){c.second();std::cout<<"PASS "<<c.first<<'\n';}std::cout<<cases.size()<<" device tests passed\n";
}
